"""Bundled emoji shortcode dataset (assets/emoji.json, generated by
scripts/gen_emoji_data.py from the `emoji` package — no runtime dependency).

Each entry is (shortcode, char, category); category ordering for the picker's
Emojis tab is defined here, with Component last (Chatterino parity).
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

log = logging.getLogger(__name__)

DATASET_PATH = Path(__file__).resolve().parent.parent / "assets" / "emoji.json"

# Picker tab order for the Emojis list; Component is appended last.
CATEGORY_ORDER = (
    "Smileys & Emotion",
    "People & Body",
    "Animals & Nature",
    "Food & Drink",
    "Travel & Places",
    "Activities",
    "Objects",
    "Symbols",
    "Flags",
    "Component",
)


@dataclass(frozen=True)
class EmojiEntry:
    shortcode: str
    char: str
    category: str


@lru_cache(maxsize=1)
def emoji_dataset() -> tuple[EmojiEntry, ...]:
    """All bundled emoji; empty tuple when the asset is missing/corrupt."""
    try:
        data = json.loads(DATASET_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, UnicodeDecodeError) as exc:
        log.warning("Could not load %s: %s — emoji completion disabled", DATASET_PATH, exc)
        return ()
    return tuple(
        EmojiEntry(shortcode=name, char=char, category=str(category))
        for name, char, category in data
        if name and char
    )
